export const CindorDataTable = defineComponent({
  name: "CindorDataTable",
  props: {
    caption: { type: String, default: "" },
    columns: { type: Array as PropType<DataTableColumn[]>, default: () => [] },
    currentPage: { type: Number, default: 1 },
    emptyMessage: { type: String, default: "No rows to display." },
    expandableRows: { type: Boolean, default: false },
    expandedRowIds: { type: Array as PropType<string[]>, default: () => [] },
    loading: { type: Boolean, default: false },
    pageSize: { type: Number, default: 10 },
    rowIdKey: { type: String, default: "id" },
    rowExpansionLabel: { type: String, default: "Row details" },
    rowExpansionSlot: { type: String, default: "row-expansion" },
    rows: { type: Array as PropType<DataTableRow[]>, default: () => [] },
    searchable: { type: Boolean, default: false },
    searchLabel: { type: String, default: "Search rows" },
    searchPlaceholder: { type: String, default: "Search rows" },
    searchQuery: { type: String, default: "" },
    sortDirection: { type: String as PropType<DataTableSortDirection>, default: "ascending" },
    sortKey: { type: String, default: "" }
  },
  emits: ["cell-edit", "update:currentPage", "page-change", "update:expandedRowIds", "row-expand", "row-action", "update:searchQuery", "search-change", "update:sortDirection", "sort-change", "update:sortKey"],
  setup(props, { attrs, emit, slots }) {
    const handleCellEdit = (event: Event) => {
      emit("cell-edit", event);
    };

    const handlePageChange = (event: Event) => {
      const target = event.currentTarget as PageHost;
      emit("update:currentPage", target.currentPage);
      emit("page-change", event);
    };

    const handleRowExpand = (event: Event) => {
      const target = event.currentTarget as ExpandedRowsHost;
      emit("update:expandedRowIds", target.expandedRowIds);
      emit("row-expand", event);
    };

    const handleRowAction = (event: Event) => {
      emit("row-action", event);
    };

    const handleSearchChange = (event: Event) => {
      const target = event.currentTarget as SearchQueryHost;
      emit("update:searchQuery", target.searchQuery);
      emit("search-change", event);
    };

    const handleSortChange = (event: Event) => {
      const target = event.currentTarget as SortHost;
      emit("update:sortDirection", target.sortDirection);
      emit("sort-change", event);
      emit("update:sortKey", target.sortKey);
    };
    return () =>
          h(
            "cindor-data-table",
            {
              ...attrs,
              caption: props.caption || undefined,
              ".columns": props.columns,
              ".currentPage": props.currentPage,
              "empty-message": props.emptyMessage,
              expandableRows: props.expandableRows || undefined,
              ".expandedRowIds": props.expandedRowIds,
              loading: props.loading || undefined,
              pageSize: props.pageSize,
              ".rowIdKey": props.rowIdKey,
              "row-expansion-label": props.rowExpansionLabel,
              "row-expansion-slot": props.rowExpansionSlot,
              ".rows": props.rows,
              searchable: props.searchable || undefined,
              "search-label": props.searchLabel,
              "search-placeholder": props.searchPlaceholder,
              searchQuery: props.searchQuery || undefined,
              ".sortDirection": props.sortDirection,
              ".sortKey": props.sortKey || undefined,
              onCellEdit: handleCellEdit,
              onPageChange: handlePageChange,
              onRowExpand: handleRowExpand,
              onRowAction: handleRowAction,
              onSearchChange: handleSearchChange,
              onSortChange: handleSortChange,
              onVnodeMounted: chainMountedVueVNodeHook(attrs.onVnodeMounted, (vnode) => {
                const element = getVueHostElement(vnode);
                if (!element) {
                  return;
                }
                applyElementProperties(element, {
                  columns: props.columns,
                  currentPage: props.currentPage,
                  expandedRowIds: props.expandedRowIds,
                  rowIdKey: props.rowIdKey,
                  rows: props.rows,
                  sortDirection: props.sortDirection,
                  sortKey: props.sortKey,
                });
                void warnIfDataTableRenderedEmpty(vnode, {
                  columns: props.columns,
                  currentPage: props.currentPage,
                  emptyMessage: props.emptyMessage,
                  expandedRowIds: props.expandedRowIds,
                  loading: props.loading,
                  rowIdKey: props.rowIdKey,
                  rows: props.rows,
                  searchQuery: props.searchQuery,
                  sortDirection: props.sortDirection,
                  sortKey: props.sortKey,
                });
              }),
              onVnodeUpdated: chainUpdatedVueVNodeHook(attrs.onVnodeUpdated, (vnode) => {
                const element = getVueHostElement(vnode);
                if (!element) {
                  return;
                }
                applyElementProperties(element, {
                  columns: props.columns,
                  currentPage: props.currentPage,
                  expandedRowIds: props.expandedRowIds,
                  rowIdKey: props.rowIdKey,
                  rows: props.rows,
                  sortDirection: props.sortDirection,
                  sortKey: props.sortKey,
                });
                void warnIfDataTableRenderedEmpty(vnode, {
                  columns: props.columns,
                  currentPage: props.currentPage,
                  emptyMessage: props.emptyMessage,
                  expandedRowIds: props.expandedRowIds,
                  loading: props.loading,
                  rowIdKey: props.rowIdKey,
                  rows: props.rows,
                  searchQuery: props.searchQuery,
                  sortDirection: props.sortDirection,
                  sortKey: props.sortKey,
                });
              }),
            },
            slots
          );
  }
});

